script.inlineScript:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    return {
        propName: "configurationTabConfig",
        value: {
            isFetchAPICalled: true,
            isLoading: true,
            limit: 5,
            offset: 0,
            pageNumber: 0,
            searchStr: event.payload.searchText.trim(),
            originalCount: api.state.configurationTabConfig.originalCount
        }
    };
}

